mapper.select:
select
cm.code_value
, cm.code_name as ticketType
, sum(tic.quantity) as purchasePair
, sum(tic.hit_pair) as hitPair
, sum(tic.stake) as purchaseAmount
, sum(tic.collection_amount) as collectionAmount
from
purchases pur
left outer join tickets tic
on pur.id = tic.purchase_id
and pur.is_deleted = false
and tic.is_deleted = false
left outer join code_master cm
on cm.code_category = '券種'
and tic.ticket_code = cm.code_value
and cm.is_deleted = false


        #{purchaseDateStart} <= pur.purchase_date


        and pur.purchase_date <= #{purchaseDateEnd}


        and pur.venue = #{venue}


        and pur.race_no = #{raceNo}


        and pur.grade = #{grade}


        and pur.race_name = #{raceName}


        and pur.course = #{course}


        and #{distanceStart} <= pur.distance


        and pur.distance <= #{distanceEnd}


        and pur.course_condition = #{courseCondition}


        and pur.age = #{age}


        and pur.weight = #{weight}


group by
cm.code_name
, cm.code_value
order by cm.code_value
